diff --git a/rust/fslc/tests/reviewgraphen_generated_calibration_18.rs b/rust/fslc/tests/reviewgraphen_generated_calibration_18.rs
new file mode 100644
--- /dev/null
+++ b/rust/fslc/tests/reviewgraphen_generated_calibration_18.rs
@@ -0,0 +1,24 @@
+// SPDX-License-Identifier: Apache-2.0
+
+use std::process::Command;
+
+use serde_json::Value;
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let output = Command::new(env!("CARGO_BIN_EXE_fslc"))
+        .args(["ai", "compare", "--unknown"])
+        .output()
+        .expect("run native fslc");
+
+    assert_eq!(output.status.code(), Some(2));
+    assert!(output.stderr.is_empty());
+    let value: Value = serde_json::from_slice(&output.stdout).unwrap_or_else(|error| {
+        panic!(
+            "invalid JSON: {error}; stderr={}",
+            String::from_utf8_lossy(&output.stderr)
+        )
+    });
+    assert_eq!(value["result"], "error");
+    assert_eq!(value["kind"], "usage");
+    assert_eq!(value["message"], "unknown ai compare option '--unknown'");
+}
